import { defineConfig } from '@playwright/test'

const preview = process.env.MD_MANAGER_TEST_PREVIEW === '1'
const baseURL = `http://127.0.0.1:${process.env.MD_MANAGER_WEB_PORT ?? (preview ? 4173 : 5173)}`

export default defineConfig({
  testDir: './tests',
  testMatch: '**/*.spec.ts',
  // Browser tests mutate (and then clean) the shared fixture tree, so they must never run concurrently.
  workers: 1,
  fullyParallel: false,
  use: {
    baseURL,
    browserName: 'chromium',
    // Reduced motion makes the force layout settle synchronously, so nothing waits on animation.
    reducedMotion: 'reduce',
  },
  webServer: [
    {
      command: 'npm run start:api',
      url: `http://127.0.0.1:${process.env.MD_MANAGER_API_PORT ?? 3001}/api/entries`,
      reuseExistingServer: false,
      timeout: 30_000,
    },
    {
      command: preview ? 'npm run preview' : 'npm run dev:web',
      url: baseURL,
      reuseExistingServer: false,
      timeout: 30_000,
    },
  ],
})
import { createHash, randomBytes } from 'node:crypto'
import fs, { type FileHandle } from 'node:fs/promises'
import { constants } from 'node:fs'
import { isAbsolute, relative, resolve, sep } from 'node:path'

export type Source = 'Pi' | 'Claude'

/** The only directories a request can ever address. A request source is mapped, never used as a directory name. */
const SOURCE_DIRECTORIES: Readonly<Record<Source, string>> = { Pi: 'pi', Claude: 'claude' }

export function isSource(value: unknown): value is Source {
  return value === 'Pi' || value === 'Claude'
}

export function isMarkdownName(name: string): boolean {
  return name.toLowerCase().endsWith('.md')
}

export function sha256(bytes: Buffer): string {
  return createHash('sha256').update(bytes).digest('hex')
}

/** A rejected request: `status` is the HTTP status, `code` is stable and machine-readable, `message` is safe to send. */
export class RequestError extends Error {
  readonly status: number
  readonly code: string
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

export class PathError extends RequestError {
  constructor(status: 400 | 404, message: string, code = status === 400 ? 'INVALID_PATH' : 'NOT_FOUND') {
    super(status, code, message)
  }
}

const INVALID_PATH = 'The file path is invalid.'
export const NOT_FOUND = 'The file was not found or is not a Markdown file.'
export const HASH_CONFLICT_MESSAGE = 'This file changed on disk. Reload it or copy your draft.'

/**
 * Splits a relative path into safe components. Rejects before any normalisation: `..` and `.` components,
 * empty components (leading, trailing or doubled separators), backslashes, NULs and absolute forms,
 * including Windows drive letters and UNC prefixes.
 */
export function splitRelativePath(path: string): string[] {
  if (typeof path !== 'string' || path.length === 0) throw new PathError(400, INVALID_PATH)
  if (path.includes('\0') || path.includes('\\')) throw new PathError(400, INVALID_PATH)
  if (path.startsWith('/') || isAbsolute(path) || /^[A-Za-z]:/.test(path)) throw new PathError(400, INVALID_PATH)
  const components = path.split('/')
  for (const component of components) {
    if (component === '' || component === '.' || component === '..') throw new PathError(400, INVALID_PATH)
  }
  return components
}

/** Runs mutations one at a time so two app requests can never interleave their check-then-write steps. */
export class MutationQueue {
  private tail: Promise<unknown> = Promise.resolve()
  run<T>(task: () => Promise<T>): Promise<T> {
    const result = this.tail.then(task, task)
    this.tail = result.catch(() => undefined)
    return result
  }
}

export type FixtureRoot = { directory: string; handle: FileHandle; mutations: MutationQueue }
export type ReadFile = (file: FileHandle) => Promise<Buffer>
export type FileDocument = { source: Source; path: string; content: string; hash: string }

const DIRECTORY_FLAGS = constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW
const FILE_FLAGS = constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK
export const CREATE_FLAGS = constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW
const CAPABILITY_ERROR = 'Secure file reads require Linux with mounted procfs at /proc/self/fd.'

/** No pathname fallback: Node lacks openat, so descriptor-relative traversal requires Linux procfs. */
export async function openFixtureRoot(directory: string): Promise<FixtureRoot> {
  if (process.platform !== 'linux' || !constants.O_NOFOLLOW || !constants.O_DIRECTORY) {
    throw new Error(CAPABILITY_ERROR)
  }
  try {
    const stats = await fs.statfs('/proc/self/fd')
    if (stats.type !== 0x9fa0) throw new Error('Not procfs')
  } catch (cause) { throw new Error(CAPABILITY_ERROR, { cause }) }
  // The configured root and its ancestors are trusted startup configuration, not request input.
  // Pin it once; every source/descendant is subsequently opened relative to a retained descriptor.
  const handle = await fs.open(resolve(directory), DIRECTORY_FLAGS)
  try {
    const probe = await fs.open(`/proc/self/fd/${handle.fd}`, constants.O_RDONLY | constants.O_DIRECTORY)
    await probe.close()
  } catch (cause) {
    await handle.close()
    throw new Error(CAPABILITY_ERROR, { cause })
  }
  return { directory: resolve(directory), handle, mutations: new MutationQueue() }
}

function filesystemError(error: unknown): never {
  const code = (error as NodeJS.ErrnoException)?.code
  if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'ELOOP') {
    throw new PathError(404, NOT_FOUND)
  }
  throw error
}

/** A descriptor-relative path: the parent is an already-open directory, the name is one validated component. */
export function at(parent: FileHandle, name: string): string {
  return `/proc/self/fd/${parent.fd}/${name}`
}

export type Target = { source: Source; components: string[] }

/** Validates source and path lexically and returns the safe components. Nothing on disk is touched. */
export function validateEntryPath(source: unknown, path: unknown, kind: 'file' | 'folder' | 'any'): Target {
  if (!isSource(source)) throw new PathError(400, 'The source must be Pi or Claude.', 'INVALID_SOURCE')
  if (typeof path !== 'string') throw new PathError(400, INVALID_PATH)
  const components = splitRelativePath(path)
  const sourceRoot = resolve('/', SOURCE_DIRECTORIES[source])
  const inside = relative(sourceRoot, resolve(sourceRoot, ...components))
  if (!inside || inside === '..' || inside.startsWith(`..${sep}`) || isAbsolute(inside)) {
    throw new PathError(400, INVALID_PATH)
  }
  const markdown = isMarkdownName(components[components.length - 1])
  if (kind === 'file' && !markdown) throw new PathError(400, 'The file name must end in .md.')
  if (kind === 'folder' && markdown) throw new PathError(400, 'A folder name must not end in .md.')
  return { source, components }
}

/** Read/write validation: a non-Markdown name is reported as an unavailable file, not a malformed path. */
export function validateMarkdownPath(source: unknown, path: unknown): Target {
  const target = validateEntryPath(source, path, 'any')
  if (!isMarkdownName(target.components[target.components.length - 1])) throw new PathError(404, NOT_FOUND)
  return target
}

/**
 * Walks from the pinned root to the directory containing the target, one no-follow open per component.
 * O_NOFOLLOW applies to ONE component at each step; the parent is an already-open directory.
 * Rename/symlink replacement can therefore only yield the pinned original or an unavailable target,
 * never re-resolve an earlier component. Keep all handles alive until the operation completes.
 */
export async function withParentDirectory<T>(
  root: FixtureRoot, source: Source, components: string[],
  operation: (parent: FileHandle, name: string, track: (handle: FileHandle) => void) => Promise<T>,
): Promise<T> {
  const handles: FileHandle[] = []
  try {
    let parent = root.handle
    for (const component of [SOURCE_DIRECTORIES[source], ...components.slice(0, -1)]) {
      parent = await fs.open(at(parent, component), DIRECTORY_FLAGS)
      handles.push(parent)
    }
    return await operation(parent, components[components.length - 1], handle => handles.push(handle))
  } catch (error) { filesystemError(error) }
  finally { await Promise.all(handles.reverse().map(handle => handle.close())) }
}

/** Opens the final component no-follow and non-blocking and requires a regular file. */
export async function openRegularFile(parent: FileHandle, name: string): Promise<FileHandle> {
  // ENXIO here identifies an unopenable special target (e.g. a socket), not a read failure.
  // O_NONBLOCK lets us fstat/reject FIFOs without waiting for a writer.
  const file = await fs.open(at(parent, name), FILE_FLAGS).catch(error => {
    if ((error as NodeJS.ErrnoException).code === 'ENXIO') throw new PathError(404, NOT_FOUND)
    throw error
  })
  try {
    if (!(await file.stat()).isFile()) throw new PathError(404, NOT_FOUND)
  } catch (error) {
    await file.close()
    throw error
  }
  return file
}

/** Reusable path validator with a descriptor-scoped operation, never a checked pathname. */
export async function withMarkdownFile<T>(
  root: FixtureRoot, source: unknown, path: unknown,
  operation: (file: FileHandle, identity: { source: Source; path: string }) => Promise<T>,
): Promise<T> {
  const validated = validateMarkdownPath(source, path)
  return withParentDirectory(root, validated.source, validated.components, async (parent, name, track) => {
    const file = await openRegularFile(parent, name)
    track(file)
    return operation(file, { source: validated.source, path: validated.components.join('/') })
  })
}

/** Reads from the validated descriptor once; content and SHA-256 use that same buffer. */
export async function readMarkdownFile(
  root: FixtureRoot, source: unknown, path: unknown, readFile: ReadFile = file => file.readFile(),
): Promise<FileDocument> {
  return withMarkdownFile(root, source, path, async (file, identity) => {
    const bytes = await readFile(file)
    return { ...identity, content: bytes.toString('utf8'), hash: sha256(bytes) }
  })
}

export type WriteResult = { source: Source; path: string; hash: string }

/**
 * Hash-guarded atomic replacement, serialized with every other app mutation:
 * open the pinned original, compare its bytes to the expected hash, stage the new bytes in an exclusively
 * created sibling temp file carrying the original mode, re-verify the original's identity and bytes,
 * then rename the temp file over it. Any handled failure removes the temp file and leaves the original.
 * Residual limit: an external writer racing between the final re-check and the rename is not detected.
 */
export async function writeMarkdownFile(
  root: FixtureRoot, source: unknown, path: unknown, content: string, expectedHash: string,
): Promise<WriteResult> {
  const validated = validateMarkdownPath(source, path)
  return root.mutations.run(() => withParentDirectory(root, validated.source, validated.components, async (parent, name, track) => {
    const original = await openRegularFile(parent, name)
    track(original)
    const stats = await original.stat()
    if (sha256(await original.readFile()) !== expectedHash) throw new RequestError(409, 'HASH_CONFLICT', HASH_CONFLICT_MESSAGE)

    const bytes = Buffer.from(content, 'utf8')
    const tempName = `.${name}.${randomBytes(8).toString('hex')}.tmp`
    const temp = await fs.open(at(parent, tempName), CREATE_FLAGS, 0o600)
    try {
      await temp.chmod(stats.mode & 0o7777)
      await temp.writeFile(bytes)
      await temp.sync()
      await temp.close()
      // Staging took time: the same name must still be the same regular file with the expected bytes.
      const fresh = await openRegularFile(parent, name).catch(error => {
        if (error instanceof PathError) throw new RequestError(409, 'HASH_CONFLICT', HASH_CONFLICT_MESSAGE)
        throw error
      })
      track(fresh)
      const freshStats = await fresh.stat()
      const unchanged = freshStats.ino === stats.ino && freshStats.dev === stats.dev && sha256(await fresh.readFile()) === expectedHash
      if (!unchanged) throw new RequestError(409, 'HASH_CONFLICT', HASH_CONFLICT_MESSAGE)
      await fs.rename(at(parent, tempName), at(parent, name))
    } catch (error) {
      await temp.close().catch(() => undefined)
      await fs.unlink(at(parent, tempName)).catch(() => undefined)
      throw error
    }
    return { source: validated.source, path: validated.components.join('/'), hash: sha256(bytes) }
  }))
}
import fs, { type FileHandle } from 'node:fs/promises'
import type { Stats } from 'node:fs'
import {
  CREATE_FLAGS, NOT_FOUND, PathError, RequestError, at, isMarkdownName, isSource, openRegularFile, validateEntryPath,
  withParentDirectory, type FixtureRoot, type Source, type Target,
} from './files.ts'

/**
 * Bounded file and folder operations. Every step is descriptor-relative (see files.ts); nothing here
 * re-resolves a validated pathname. All operations run through the same serial queue as content saves.
 *
 * Collision policy: a filesystem probe (lstat of the destination name inside its open parent) refuses
 * anything that exists, including dangling symlinks; creation uses O_EXCL/mkdir, file renames use
 * link + unlink (link fails on an existing name), folder renames use rename after the probe.
 */
export type MutationRequest =
  | { op: 'create-file'; source: Source; path: string; content: string }
  | { op: 'create-folder'; source: Source; path: string }
  | { op: 'rename'; source: Source; path: string; destinationPath: string }
  | { op: 'move'; source: Source; path: string; destinationPath: string }
  | { op: 'delete'; source: Source; path: string }
  | { op: 'copy'; source: Source; path: string; destinationSource: Source; destinationPath: string }

export type MutationResult = { status: 200 | 201; body: { op: string; source: Source; path: string; destinationSource?: Source; destinationPath?: string } }

const DESTINATION_EXISTS = new RequestError(409, 'DESTINATION_EXISTS', 'Something already exists at that destination. Choose another name.')
const FOLDER_NOT_EMPTY = new RequestError(409, 'FOLDER_NOT_EMPTY', 'The folder is not empty. Only empty folders can be renamed, moved or deleted.')
const NO_CHANGE = new RequestError(409, 'NO_CHANGE', 'The destination is the same as the current path.')

function field(body: Record<string, unknown>, name: string): string {
  const value = body[name]
  if (typeof value !== 'string') throw new RequestError(400, 'INVALID_BODY', `The ${name} field must be a string.`)
  return value
}

/** Parses the discriminated request body. Source names are checked here; paths are validated by the operation. */
export function parseMutationBody(body: unknown): MutationRequest {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new RequestError(400, 'INVALID_BODY', 'The request body must be a JSON object with an op, source and path.')
  }
  const record = body as Record<string, unknown>
  const source = record.source
  if (!isSource(source)) throw new RequestError(400, 'INVALID_SOURCE', 'The source must be Pi or Claude.')
  const path = field(record, 'path')
  switch (record.op) {
    case 'create-file': {
      const content = record.content === undefined ? '' : record.content
      if (typeof content !== 'string') throw new RequestError(400, 'INVALID_CONTENT', 'The content must be a string.')
      return { op: 'create-file', source, path, content }
    }
    case 'create-folder':
      return { op: 'create-folder', source, path }
    case 'delete':
      return { op: 'delete', source, path }
    case 'rename':
    case 'move': {
      if (record.destinationSource !== undefined && record.destinationSource !== source) {
        throw new RequestError(400, 'INVALID_SOURCE', `A ${record.op} stays within the same source.`)
      }
      return { op: record.op, source, path, destinationPath: field(record, 'destinationPath') }
    }
    case 'copy': {
      const destinationSource = record.destinationSource
      if (!isSource(destinationSource)) throw new RequestError(400, 'INVALID_SOURCE', 'The destination source must be Pi or Claude.')
      if (destinationSource === source) throw new RequestError(400, 'INVALID_SOURCE', 'Copy targets the other source only.')
      return { op: 'copy', source, path, destinationSource, destinationPath: field(record, 'destinationPath') }
    }
    default:
      throw new RequestError(400, 'INVALID_OP', 'The op must be create-file, create-folder, rename, move, delete or copy.')
  }
}

function sameComponents(a: string[], b: string[]): boolean {
  return a.length === b.length && a.every((component, index) => component === b[index])
}

/** lstat inside the open parent: reports whatever occupies the name, including a dangling symlink. */
async function probe(parent: FileHandle, name: string): Promise<Stats | null> {
  try {
    return await fs.lstat(at(parent, name))
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null
    throw error
  }
}

async function assertAbsent(parent: FileHandle, name: string): Promise<void> {
  if (await probe(parent, name)) throw DESTINATION_EXISTS
}

/** Resolves an existing mutation target: a regular Markdown file or a directory, never a symlink or other type. */
async function existingTarget(parent: FileHandle, name: string): Promise<'file' | 'folder'> {
  const stats = await probe(parent, name)
  if (!stats || stats.isSymbolicLink()) throw new PathError(404, NOT_FOUND)
  if (stats.isDirectory()) return 'folder'
  if (stats.isFile() && isMarkdownName(name)) return 'file'
  throw new PathError(404, NOT_FOUND)
}

async function assertEmptyFolder(parent: FileHandle, name: string): Promise<void> {
  // Includes hidden and non-Markdown entries the listing never shows.
  if ((await fs.readdir(at(parent, name))).length > 0) throw FOLDER_NOT_EMPTY
}

function conflictFromErrno(error: unknown): never {
  const code = (error as NodeJS.ErrnoException)?.code
  if (code === 'EEXIST') throw DESTINATION_EXISTS
  if (code === 'ENOTEMPTY') throw FOLDER_NOT_EMPTY
  throw error
}

async function createFile(root: FixtureRoot, target: Target, content: string): Promise<void> {
  await withParentDirectory(root, target.source, target.components, async (parent, name) => {
    await assertAbsent(parent, name)
    const file = await fs.open(at(parent, name), CREATE_FLAGS, 0o644).catch(conflictFromErrno)
    try { await file.writeFile(Buffer.from(content, 'utf8')) } finally { await file.close() }
  })
}

async function createFolder(root: FixtureRoot, target: Target): Promise<void> {
  await withParentDirectory(root, target.source, target.components, async (parent, name) => {
    await assertAbsent(parent, name)
    await fs.mkdir(at(parent, name)).catch(conflictFromErrno)
  })
}

async function deleteEntry(root: FixtureRoot, target: Target): Promise<void> {
  await withParentDirectory(root, target.source, target.components, async (parent, name) => {
    const kind = await existingTarget(parent, name)
    if (kind === 'file') {
      await fs.unlink(at(parent, name))
    } else {
      await assertEmptyFolder(parent, name)
      await fs.rmdir(at(parent, name)).catch(conflictFromErrno)
    }
  })
}

/** Rename and move share one implementation; the caller has already checked the parent relationship. */
async function relocate(root: FixtureRoot, from: Target, to: Target): Promise<void> {
  if (sameComponents(from.components, to.components)) throw NO_CHANGE
  const fromParent = from.components.slice(0, -1)
  if (to.components.length > from.components.length && sameComponents(from.components, to.components.slice(0, from.components.length))) {
    throw new PathError(400, 'A folder cannot be moved into itself.')
  }
  await withParentDirectory(root, from.source, from.components, async (sourceParent, sourceName) => {
    const kind = await existingTarget(sourceParent, sourceName)
    const destinationName = to.components[to.components.length - 1]
    if (kind === 'file' && !isMarkdownName(destinationName)) throw new PathError(400, 'The file name must end in .md.')
    if (kind === 'folder' && isMarkdownName(destinationName)) throw new PathError(400, 'A folder name must not end in .md.')
    if (kind === 'folder') await assertEmptyFolder(sourceParent, sourceName)
    const run = async (destinationParent: FileHandle) => {
      await assertAbsent(destinationParent, destinationName)
      if (kind === 'file') {
        // link() refuses an existing destination atomically; the old name is removed only once the new one exists.
        await fs.link(at(sourceParent, sourceName), at(destinationParent, destinationName)).catch(conflictFromErrno)
        try {
          await fs.unlink(at(sourceParent, sourceName))
        } catch (error) {
          await fs.unlink(at(destinationParent, destinationName)).catch(() => undefined)
          throw error
        }
      } else {
        await fs.rename(at(sourceParent, sourceName), at(destinationParent, destinationName)).catch(conflictFromErrno)
      }
    }
    if (sameComponents(fromParent, to.components.slice(0, -1))) await run(sourceParent)
    else await withParentDirectory(root, to.source, to.components, destinationParent => run(destinationParent))
  })
}

async function copyFile(root: FixtureRoot, from: Target, to: Target): Promise<void> {
  await withParentDirectory(root, from.source, from.components, async (sourceParent, sourceName, track) => {
    const source = await openRegularFile(sourceParent, sourceName)
    track(source)
    const stats = await source.stat()
    const bytes = await source.readFile()
    await withParentDirectory(root, to.source, to.components, async (destinationParent, destinationName) => {
      await assertAbsent(destinationParent, destinationName)
      const file = await fs.open(at(destinationParent, destinationName), CREATE_FLAGS, 0o644).catch(conflictFromErrno)
      try {
        await file.chmod(stats.mode & 0o7777)
        await file.writeFile(bytes)
      } finally { await file.close() }
    })
  })
}

/** Validates everything lexically, then runs the operation inside the shared serial queue. */
export async function performMutation(root: FixtureRoot, request: MutationRequest): Promise<MutationResult> {
  const { op, source, path } = request
  return root.mutations.run(async (): Promise<MutationResult> => {
    switch (op) {
      case 'create-file': {
        const target = validateEntryPath(source, path, 'file')
        await createFile(root, target, request.content)
        return { status: 201, body: { op, source, path: target.components.join('/') } }
      }
      case 'create-folder': {
        const target = validateEntryPath(source, path, 'folder')
        await createFolder(root, target)
        return { status: 201, body: { op, source, path: target.components.join('/') } }
      }
      case 'delete': {
        const target = validateEntryPath(source, path, 'any')
        await deleteEntry(root, target)
        return { status: 200, body: { op, source, path: target.components.join('/') } }
      }
      case 'rename':
      case 'move': {
        const from = validateEntryPath(source, path, 'any')
        const to = validateEntryPath(source, request.destinationPath, 'any')
        if (op === 'rename' && !sameComponents(from.components.slice(0, -1), to.components.slice(0, -1))) {
          throw new PathError(400, 'A rename keeps the same parent folder. Use move to change folders.')
        }
        await relocate(root, from, to)
        return { status: 200, body: { op, source, path: from.components.join('/'), destinationSource: source, destinationPath: to.components.join('/') } }
      }
      case 'copy': {
        const from = validateEntryPath(source, path, 'any')
        if (!isMarkdownName(from.components[from.components.length - 1])) throw new PathError(404, NOT_FOUND)
        const to = validateEntryPath(request.destinationSource, request.destinationPath, 'file')
        await copyFile(root, from, to)
