import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from 'react'
import { fileToPathname, type FileRef } from '../graph/model.ts'
import { EditingSession, type EditingState } from './EditingSession.tsx'
import type { Snapshot } from './editSession.ts'
import { Markdown } from './Markdown.tsx'
import { analyzeText, contentHash, type TextAnalysis } from './serialize.ts'
import type { DocumentState } from './useDocument.ts'

type Tab = 'rendered' | 'source'
const TABS: ReadonlyArray<{ id: Tab; label: string }> = [
  { id: 'rendered', label: 'Rendered' },
  { id: 'source', label: 'Source' },
]

type Props = {
  fileRef: FileRef
  state: DocumentState
  onBack: () => void
  onRetry: () => void
  onAnnounce: (message: string) => void
  onEditingChange: (state: EditingState | null) => void
  /** Current editing state, for copy labelling and disabling while a save is pending. */
  editingState: EditingState | null
  onOperation: (op: 'rename' | 'move' | 'delete' | 'copy') => void
  guardLeave: (leave: () => void) => void
}

/** Whether the loaded text can be edited and written back byte for byte. */
type Editability =
  | { status: 'checking' }
  | { status: 'editable'; analysis: TextAnalysis }
  | { status: 'unavailable'; reason: string }

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

/** Document shell: identity header, Back to folder, Rendered/Source tabs, load states, and the editing session. */
export function DocumentView({ fileRef, state, editingState, onBack, onRetry, onAnnounce, onEditingChange, onOperation, guardLeave }: Props) {
  const key = fileToPathname(fileRef)
  const name = baseName(fileRef.path)
  const otherSource = fileRef.source === 'Pi' ? 'Claude' : 'Pi'
  const headingRef = useRef<HTMLHeadingElement>(null)
  const editButtonRef = useRef<HTMLButtonElement>(null)
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([])
  const [tab, setTab] = useState<Tab>('rendered')
  const [editing, setEditing] = useState(false)
  // After editing, the read-only view shows the last acknowledged content, not the original fetch.
  const [override, setOverride] = useState<{ ref: FileRef; document: Snapshot } | null>(null)
  const [tabKey, setTabKey] = useState(key)
  // Opening a different document always starts on Rendered, read-only.
  if (tabKey !== key) {
    setTabKey(key)
    setTab('rendered')
    setEditing(false)
    setOverride(null)
  }

  const loaded = state.status === 'ready' ? state.document : null
  const shown: Snapshot | null = loaded ? (override && override.ref === state.ref ? override.document : loaded) : null

  // Focus moves to the document entry point when a document is opened (not when switching tabs).
  useEffect(() => { headingRef.current?.focus() }, [key])

  // Editability: same line ending throughout, and the UTF-8 re-encoding must hash to the bytes the server read.
  // The hash check is asynchronous; until it settles for this exact document, editing is unavailable.
  const [hashCheck, setHashCheck] = useState<{ document: Snapshot; matches: boolean } | null>(null)
  useEffect(() => {
    if (!loaded) return
    let cancelled = false
    void contentHash(loaded.content).then(hash => { if (!cancelled) setHashCheck({ document: loaded, matches: hash === loaded.hash }) })
    return () => { cancelled = true }
  }, [loaded])
  let editability: Editability = { status: 'checking' }
  if (loaded && hashCheck?.document === loaded) {
    const analysis = analyzeText(loaded.content)
    if (!analysis.editable) editability = { status: 'unavailable', reason: analysis.reason }
    else if (!hashCheck.matches) editability = { status: 'unavailable', reason: 'it is not valid UTF-8, so its bytes cannot be reproduced' }
    else editability = { status: 'editable', analysis }
  }

  const acknowledged = useCallback((snapshot: Snapshot) => {
    setOverride(previous => (previous && previous.ref === state.ref && previous.document === snapshot ? previous : { ref: state.ref, document: snapshot }))
  }, [state.ref])
  const exitEditing = useCallback((acknowledged: Snapshot) => {
    setOverride({ ref: state.ref, document: acknowledged })
    setEditing(false)
    setTab('rendered')
    onAnnounce(`Finished editing ${name}.`)
    requestAnimationFrame(() => editButtonRef.current?.focus())
  }, [name, onAnnounce, state.ref])

  const onTabKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    setTab(TABS[next].id)
    tabRefs.current[next]?.focus()
  }

  let panel: React.ReactNode
  if (state.status === 'loading') {
    panel = <p className="document-message">Loading {name}…</p>
  } else if (state.status === 'error') {
    const explanation = state.kind === 'missing'
      ? `${name} was not found in ${fileRef.source} or is unavailable. It may have been renamed or removed.`
      : state.kind === 'invalid'
        ? `The link to ${name} is invalid.`
        : `${name} could not be loaded. ${state.message}`
    panel = (
      <div className="document-message document-error" role="alert">
        <p>{explanation}</p>
        <p className="document-actions">
          {state.kind === 'failed' && <button type="button" className="button" onClick={onRetry}>Retry</button>}
          <span>Use Back to folder to return to browsing.</span>
        </p>
      </div>
    )
  } else if (shown) {
    // Keep the memoized Markdown subtree mounted across tab switches: large files should not be
    // parsed again just to return from Source. Only the selected tab is visible/accessibility-exposed.
    panel = (
      <>
        <div hidden={tab !== 'rendered'}>
          {shown.content === ''
            ? <p className="document-message">This file is empty.</p>
            : <Markdown content={shown.content} />}
        </div>
        {tab === 'source' && <>
          {shown.content === '' && <p className="document-message">This file is empty.</p>}
          <pre className="document-source" data-testid="document-source" tabIndex={0}>{shown.content}</pre>
        </>}
      </>
    )
  }

  const canEdit = shown !== null && editability.status === 'editable'
  const body = editing && shown && canEdit
    ? (
      <div className="document-editing">
        <EditingSession
          key={key}
          fileRef={fileRef}
          document={shown}
          analysis={editability.status === 'editable' ? editability.analysis : analyzeText(shown.content)}
          onAnnounce={onAnnounce}
          onStateChange={onEditingChange}
          onAcknowledged={acknowledged}
          guardLeave={guardLeave}
          onExit={exitEditing}
        />
      </div>
    )
    : (
      <>
        <div className="tabs" role="tablist" aria-label="Document view">
          {TABS.map((candidate, index) => (
            <button
              key={candidate.id}
              ref={element => { tabRefs.current[index] = element }}
              type="button"
              role="tab"
              id={`tab-${candidate.id}`}
              className="tab"
              aria-selected={tab === candidate.id}
              aria-controls="document-panel"
              tabIndex={tab === candidate.id ? 0 : -1}
              onClick={() => setTab(candidate.id)}
              onKeyDown={onTabKeyDown}
            >
              {candidate.label}
            </button>
          ))}
        </div>
        <div className="document-panel" role="tabpanel" id="document-panel" aria-labelledby={`tab-${tab}`}>
          {panel}
        </div>
      </>
    )
  return (
    <section
      className="document"
      data-testid="document-view"
      data-hash={shown?.hash}
      aria-labelledby="document-title"
      aria-busy={state.status === 'loading'}
    >
      <header className="document-header">
        <div className="document-identity">
          <h2 id="document-title" ref={headingRef} tabIndex={-1}>{name}</h2>
          <p className="document-meta" data-testid="document-meta">
            <span className="document-source-name">{fileRef.source}</span>
            <span className="document-separator" aria-hidden="true">·</span>
            <span className="document-path">{fileRef.path}</span>
          </p>
        </div>
        <div className="document-header-actions">
          {shown && (
            <>
              <button type="button" className="button" onClick={() => onOperation('rename')}>Rename…</button>
              <button type="button" className="button" onClick={() => onOperation('move')}>Move…</button>
              <button type="button" className="button" onClick={() => onOperation('delete')}>Delete…</button>
              <button type="button" className="button" onClick={() => onOperation('copy')} disabled={editingState?.pending === true} title={editingState?.pending ? 'Wait for the save to finish.' : undefined}>
                {editingState?.dirty ? `Copy saved content to ${otherSource}…` : `Copy to ${otherSource}…`}
              </button>
            </>
          )}
          {shown && !editing && (
            <button
              ref={editButtonRef}
              type="button"
              className="button"
              onClick={() => setEditing(true)}
              disabled={!canEdit}
              aria-describedby={editability.status === 'unavailable' ? 'edit-unavailable' : undefined}
            >
              Edit
            </button>
          )}
          <button type="button" className="button" onClick={onBack}>Back to folder</button>
        </div>
      </header>
      {shown && !editing && editability.status === 'unavailable' && (
        <p className="document-notice" id="edit-unavailable" data-testid="edit-unavailable">
          This file is read-only here because {editability.reason}. Editing it in this app could not keep the file byte for byte.
        </p>
      )}
      {body}
    </section>
  )
}
import type { ReactNode } from 'react'
import { Modal } from '../ui/Modal.tsx'

type Props = {
  title: string
  children: ReactNode
  confirmLabel: string
  cancelLabel?: string
  /** Destructive confirmations start with focus on Cancel. */
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
  onCancel: () => void
}

export function ConfirmDialog({ title, children, confirmLabel, cancelLabel = 'Cancel', destructive = false, pending = false, onConfirm, onCancel }: Props) {
  return (
    <Modal title={title} initialFocus={destructive ? 'cancel' : 'confirm'} onCancel={onCancel}>
      <form method="dialog" onSubmit={event => { event.preventDefault(); if (!pending) onConfirm() }}>
        <div className="confirm-description">{children}</div>
        <div className="confirm-actions">
          <button type="button" className="button" data-dialog-cancel onClick={onCancel} disabled={pending}>{cancelLabel}</button>
          <button type="submit" className={destructive ? 'button button-danger' : 'button'} data-dialog-confirm disabled={pending} aria-busy={pending}>{confirmLabel}</button>
        </div>
      </form>
    </Modal>
  )
}
import { useMemo, useState, type FormEvent } from 'react'
import { nodeId, type FolderRef, type Source, type TreeIndex } from '../graph/model.ts'
import { Modal } from '../ui/Modal.tsx'
import { OperationError, performOperation, type MutationRequest, type MutationResponse } from './api.ts'
import { validateName } from './validate.ts'

/** What the user asked to do and to what. Folders use `kind: 'folder'`; a source root is a folder with path ''. */
export type OperationTarget =
  | { kind: 'folder'; ref: FolderRef }
  | { kind: 'file'; ref: { source: Source; path: string }; draftDirty: boolean }

export type Operation =
  | { op: 'create-file' | 'create-folder'; parent: FolderRef }
  | { op: 'rename' | 'move' | 'delete'; target: OperationTarget }
  | { op: 'copy'; target: Extract<OperationTarget, { kind: 'file' }> }

type Props = {
  operation: Operation
  index: TreeIndex
  onCancel: () => void
  onSuccess: (operation: Operation, response: MutationResponse) => void
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

function parentPath(path: string): string {
  const cut = path.lastIndexOf('/')
  return cut === -1 ? '' : path.slice(0, cut)
}

function describeFolder(ref: FolderRef): string {
  return ref.path ? `${ref.source} / ${ref.path}` : ref.source
}

function joinPath(parent: string, name: string): string {
  return parent ? `${parent}/${name}` : name
}

/** Folders of one source, in listing order, optionally excluding a subtree (a folder cannot move into itself). */
function folderOptions(index: TreeIndex, source: Source, exclude: string | null): FolderRef[] {
  const options: FolderRef[] = []
  for (const node of index.nodes.values()) {
    if (node.source !== source || node.kind === 'file') continue
    if (exclude !== null && (node.path === exclude || node.path.startsWith(`${exclude}/`))) continue
    options.push({ source, path: node.path })
  }
  return options.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
}

const TITLES: Record<Operation['op'], string> = {
  'create-file': 'New file', 'create-folder': 'New folder', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}
const SUBMIT: Record<Operation['op'], string> = {
  'create-file': 'Create', 'create-folder': 'Create', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}

/** One labelled dialog per operation: name/destination fields, client validation, one pending request, server errors inline. */
export function OperationDialog({ operation, index, onCancel, onSuccess }: Props) {
  const { op } = operation
  const target = 'target' in operation ? operation.target : null
  const targetName = target ? baseName(target.ref.path) : ''
  const nameKind: 'file' | 'folder' = op === 'create-folder' || (target?.kind === 'folder') ? 'folder' : 'file'
  const [name, setName] = useState(op === 'rename' || op === 'copy' ? targetName : '')
  const destinationSource: Source | null = op === 'copy' ? (operation.target.ref.source === 'Pi' ? 'Claude' : 'Pi') : op === 'move' ? operation.target.ref.source : null
  const destinations = useMemo(() => {
    if (!destinationSource) return []
    const exclude = op === 'move' && operation.target.kind === 'folder' ? operation.target.ref.path : null
    const currentParent = op === 'move' ? parentPath(operation.target.ref.path) : null
    return folderOptions(index, destinationSource, exclude).filter(folder => folder.path !== currentParent)
  }, [destinationSource, index, op, operation])
  const [destination, setDestination] = useState(() => destinations[0]?.path ?? '')
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  const request = (): MutationRequest | string => {
    switch (op) {
      case 'create-file':
      case 'create-folder': {
        const invalid = validateName(name, nameKind)
        if (invalid) return invalid
        return { op, source: operation.parent.source, path: joinPath(operation.parent.path, name) }
      }
      case 'rename': {
        const invalid = validateName(name, nameKind)
        if (invalid) return invalid
        if (name === targetName) return 'Enter a different name.'
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationPath: joinPath(parentPath(operation.target.ref.path), name) }
      }
      case 'move': {
        if (destinations.length === 0) return 'There is no other folder to move this into.'
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationPath: joinPath(destination, targetName) }
      }
      case 'delete':
        return { op, source: operation.target.ref.source, path: operation.target.ref.path }
      case 'copy': {
        const invalid = validateName(name, 'file')
        if (invalid) return invalid
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationSource: destinationSource!, destinationPath: joinPath(destination, name) }
      }
    }
  }

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    if (pending) return
    const built = request()
    if (typeof built === 'string') { setError(built); return }
    setError(null)
    setPending(true)
    try {
      const response = await performOperation(built)
      onSuccess(operation, response)
    } catch (failure) {
      setError(failure instanceof OperationError ? failure.message : 'The operation failed unexpectedly.')
      setPending(false)
    }
  }

  let description: React.ReactNode
  let fields: React.ReactNode = null
  const destinationField = destinationSource && (
    <label className="field">
      <span>Destination folder</span>
      <select value={destination} onChange={event => setDestination(event.target.value)} disabled={pending || destinations.length === 0} aria-label="Destination folder">
        {destinations.map(folder => (
          <option key={nodeId(folder.source, folder.path)} value={folder.path}>{folder.path || `${folder.source} (source root)`}</option>
        ))}
      </select>
    </label>
  )
  switch (op) {
    case 'create-file':
    case 'create-folder':
      description = <p>In <span className="dialog-path">{describeFolder(operation.parent)}</span>. {op === 'create-file' ? 'The file starts empty and opens for editing.' : 'The folder starts empty.'}</p>
      fields = (
        <label className="field">
          <span>{op === 'create-file' ? 'File name' : 'Folder name'}</span>
          <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} placeholder={op === 'create-file' ? 'name.md' : 'name'} autoComplete="off" spellCheck={false} />
        </label>
      )
      break
    case 'rename':
      description = <p>Renames <span className="dialog-path">{describeFolder({ source: operation.target.ref.source, path: operation.target.ref.path })}</span> within its folder.</p>
      fields = (
        <label className="field">
          <span>New name</span>
          <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} autoComplete="off" spellCheck={false} />
        </label>
      )
      break
    case 'move':
      description = <p>Moves <span className="dialog-path">{describeFolder({ source: operation.target.ref.source, path: operation.target.ref.path })}</span> to another folder in {operation.target.ref.source}, keeping its name.</p>
      fields = destinationField
      break
    case 'delete':
      description = (
        <>
          <p>Delete <span className="dialog-path">{operation.target.ref.source} / {operation.target.ref.path}</span>?</p>
          <p>This cannot be undone in the app: there is no trash or version history, only whatever git or backups hold. {operation.target.kind === 'folder' ? 'Only an empty folder can be deleted.' : ''}</p>
        </>
      )
      break
    case 'copy':
      description = (
        <>
          <p>Copies the <strong>saved content</strong> of <span className="dialog-path">{operation.target.ref.source} / {operation.target.ref.path}</span> from disk into {destinationSource}{operation.target.draftDirty ? '; unsaved draft changes are not included' : ''}.</p>
          <p>The bytes are copied as they are, so frontmatter written for {operation.target.ref.source} may not be accepted by the {destinationSource} agent.</p>
        </>
      )
      fields = (
        <>
          {destinationField}
          <label className="field">
            <span>File name</span>
            <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} autoComplete="off" spellCheck={false} />
          </label>
        </>
      )
      break
  }

  const destructive = op === 'delete'
  return (
    <Modal title={op === 'copy' ? `Copy to ${destinationSource}` : TITLES[op]} initialFocus={fields ? 'first-field' : destructive ? 'cancel' : 'confirm'} onCancel={onCancel}>
      <form method="dialog" onSubmit={event => { void submit(event) }} aria-busy={pending}>
        <div className="confirm-description">{description}</div>
        {fields}
        {error && <p className="dialog-error" role="alert">{error}</p>}
        <div className="confirm-actions">
          <button type="button" className="button" data-dialog-cancel onClick={onCancel} disabled={pending}>Cancel</button>
          <button type="submit" className={destructive ? 'button button-danger' : 'button'} data-dialog-confirm disabled={pending} aria-busy={pending}>
            {pending ? `${SUBMIT[op]}…` : SUBMIT[op]}
          </button>
        </div>
      </form>
    </Modal>
  )
}
/**
 * Pure explicit-save state machine for one editing session of one document. No React, no network.
 *
 * - `baseline` is captured once when Edit begins and never changes until a Reload.
 * - `acknowledged` is the last content/hash the server confirmed (read or successful write).
 * - `draft` is what the editor holds now. Keystrokes only change `draft`.
 * - At most one request is `inFlight`; explicit saves while one is pending fill a single `queued` slot.
 * - A failure or conflict empties the queue; a conflict blocks Save and Revert until `reloaded`.
 */
export type Snapshot = { content: string; hash: string }
export type SaveErrorKind = 'failed' | 'conflict' | 'too-large' | 'missing'
export type SaveError = { kind: SaveErrorKind; message: string }
export type Request = { token: number; content: string; expectedHash: string; purpose: 'save' | 'revert' }
export type Session = {
  readonly baseline: Snapshot
  readonly acknowledged: Snapshot
  readonly draft: string
  readonly inFlight: Request | null
  readonly queued: { content: string } | null
  readonly error: SaveError | null
  readonly conflicted: boolean
  readonly nextToken: number
  /** Increments whenever the draft is replaced from outside the editor (Revert success, Reload). */
  readonly generation: number
}
export type SaveStatus = 'saved' | 'unsaved' | 'saving' | 'error'

export function startSession(document: Snapshot): Session {
  const snapshot = { content: document.content, hash: document.hash }
  return { baseline: snapshot, acknowledged: snapshot, draft: document.content, inFlight: null, queued: null, error: null, conflicted: false, nextToken: 1, generation: 0 }
}

export function edit(session: Session, draft: string): Session {
  return draft === session.draft ? session : { ...session, draft }
}

function send(session: Session, content: string, purpose: Request['purpose']): Session {
  const request: Request = { token: session.nextToken, content, expectedHash: session.acknowledged.hash, purpose }
  return { ...session, inFlight: request, queued: null, error: null, nextToken: session.nextToken + 1 }
}

/** Explicit Save (button, shortcut or Retry). Never sends concurrently; never sends an unchanged draft. */
export function requestSave(session: Session): Session {
  if (session.conflicted) return session
  if (session.inFlight) {
    if (session.draft === session.inFlight.content) return session.queued ? { ...session, queued: null } : session
    return { ...session, queued: { content: session.draft } }
  }
  if (session.draft === session.acknowledged.content) return session.error ? { ...session, error: null } : session
  return send(session, session.draft, 'save')
}

/** Revert restores the Edit baseline on disk through the same hash-checked pipeline. */
export function requestRevert(session: Session): Session {
  if (!canRevert(session)) return session
  return send(session, session.baseline.content, 'revert')
}

export function settleSuccess(session: Session, token: number, hash: string): Session {
  const request = session.inFlight
  if (!request || request.token !== token) return session
  const acknowledged = { content: request.content, hash }
  const reverted = request.purpose === 'revert'
  const draft = reverted ? request.content : session.draft
  const settled: Session = { ...session, acknowledged, draft, inFlight: null, error: null, conflicted: false, generation: session.generation + (reverted ? 1 : 0) }
  if (session.queued && session.queued.content !== acknowledged.content) return send(settled, session.queued.content, 'save')
  return { ...settled, queued: null }
}

export function settleFailure(session: Session, token: number, error: SaveError): Session {
  const request = session.inFlight
  if (!request || request.token !== token) return session
  return { ...session, inFlight: null, queued: null, error, conflicted: error.kind === 'conflict' }
}

/** A successful fresh read replaces baseline, acknowledged content and draft, and clears any conflict. */
export function reloaded(session: Session, document: Snapshot): Session {
  if (session.inFlight) return session
  return { ...startSession(document), nextToken: session.nextToken, generation: session.generation + 1 }
}

export function status(session: Session): SaveStatus {
  if (session.inFlight) return 'saving'
  if (session.error) return 'error'
  return session.draft === session.acknowledged.content ? 'saved' : 'unsaved'
}

export function canSave(session: Session): boolean {
  return !session.conflicted
}

export function canRevert(session: Session): boolean {
  if (session.conflicted || session.inFlight || session.queued) return false
  return session.draft !== session.baseline.content || session.acknowledged.content !== session.baseline.content
}

/** Unsaved changes or a save that has not been acknowledged: what navigation guards and beforeunload care about. */
export function hasUnacknowledgedWork(session: Session): boolean {
  return session.inFlight !== null || session.queued !== null || session.draft !== session.acknowledged.content
}

export function isPending(session: Session): boolean {
  return session.inFlight !== null || session.queued !== null
}
